menuitem.script:
if (!window.external.IsAccessPermitted(window.external.parentWindow.document.activeElement))
    this.disabled=true;
var name = String(window.external.parentWindow.document.activeElement);
if (name.substring(23,46) == "ProcSeqTKT.PhaseControl" || name.substring(23,55) == "ProcSeqTKT.ProcedurePanelControl" || name.substring(23,57) == "ProcSeqTKT.StepAndPhaseListControl")
{
    var navigationAllowed = String(window.external.parentWindow.document.activeElement.NavigationAllowed);
    if (navigationAllowed == "false") this.disabled=true;
}
return true;

if (!window.external.IsAccessPermitted(window.external.parentWindow.document.activeElement))
    this.disabled=true;
var name = String(window.external.parentWindow.document.activeElement);
if (name.substring(23,46) == "ProcSeqTKT.PhaseControl" || name.substring(23,55) == "ProcSeqTKT.ProcedurePanelControl" || name.substring(23,57) == "ProcSeqTKT.StepAndPhaseListControl")
{
    var navigationAllowed = String(window.external.parentWindow.document.activeElement.NavigationAllowed);
    if (navigationAllowed == "false") this.disabled=true;
}
return true;

var objHdxPopup;
objHdxPopup = window.external.parentWindow.document.getElementById("HDXPopupBehavior");
if (objHdxPopup!= null)
{
    objHdxPopup.CreatePopupWindow3("sysProcedureExplorer.htm?ProcedureName=" + window.external.parentWindow.document.activeElement.ProcedureName,
        window.external.parentWindow.document.body.offsetWidth / 2 - 650 / 2, window.external.parentWindow.document.body.offsetHeight /2 - 700 / 2, 650, 700, 0, false, true);
}
window.external.CloseShortcutMenu();

var strPointName,objPopupWindow,objHdxPopup;
objHdxPopup = window.external.parentWindow.document.getElementById("HDXPopupBehavior");
if (objHdxPopup!= null)
{ 
    var controlType = String(window.external.parentWindow.document.activeElement);
    if (controlType.substring(23,45) == "ProcSeqTKT.UnitControl" || controlType.substring(23,49) == "ProcSeqTKT.UnitListControl")
    {
        strPointName = window.external.parentWindow.document.activeElement.UnitName;
        if (strPointName == "")
        {
            alert("UnitName is empty!!! Need to decide what to do here...");
        }
    }
    else
    {
        strPointName = window.external.parentWindow.document.activeElement.ProcedureName;
        if (strPointName == "")
        {
            alert("ProcedureName is empty!!! Need to decide what to do here...");
        }
    }
    
    if (strPointName != "")
    {
        objPopupWindow = objHdxPopup.FindPopup("sysPopUpChartView.htm");						
        if (objPopupWindow == null)
        {
            objHdxPopup.CreatePopupWindow("sysPopUpChartView.htm?CurrentPoint=" + strPointName, 1, 1, 1);
        }
        else
        {
            objPopupWindow.close();
            objHdxPopup.CreatePopupWindow("sysPopUpChartView.htm?CurrentPoint=" + strPointName, 1, 1, 1);
        }
     }
}
window.external.CloseShortcutMenu();
